import React, { useState } from 'react';
import '../Styles/style.css';

export default function Navbar() {
    const [isOpen, setIsOpen] = useState(false);

    const closeMenu = () => setIsOpen(false);

    return (
        <nav className="navbar">
            {/* Logo */}
            <div className="nav-logo" onClick={closeMenu}>
                MonLogo
            </div>

            {/* Bouton Hamburger */}
            <button
                className={`hamburger ${isOpen ? 'open' : ''}`}
                onClick={() => setIsOpen(!isOpen)}
                aria-label="Menu de navigation"
            >
                <span className="bar"></span>
                <span className="bar"></span>
                <span className="bar"></span>
            </button>

            {/* Liens du menu déroulant (du haut vers le bas) */}
            <div className={`nav-links ${isOpen ? 'active' : ''}`}>
                <a href="../View/Page1" onClick={closeMenu}>Page 1</a>
                <a href="../View/Page2" onClick={closeMenu}>Page 2</a>
            </div>

            {/* Voile d'arrière-plan si le menu est ouvert */}
            {isOpen && <div className="menu-overlay" onClick={closeMenu}></div>}
        </nav>
    );
}
